configureCuratedShop();
const itemSlot=i=>i.slot||i.type;
const roomName=()=>items.find(i=>i.id===(state.equipped.Rooms||'cozy'))?.name||'The cozy corner';
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function showModal(html){$('#modal-content').innerHTML=html;modal.showModal()}$('.close').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal)modal.close()});
function go(p){mealJob++;page=p;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===p));$('#page-label').textContent=({home:'MY LITTLE WORLD',wardrobe:'WARDROBE & SHOP',games:'THE PLAYROOM',})[p];render()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b)go(b.dataset.page)});
const greeting=(title,sub,eye='A LITTLE MOMENT FOR YOU')=>`<div class="greeting"><div><div class="eyebrow">${eye}</div><h1>${title}</h1><p>${sub}</p></div><span class="date">${new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'})}</span></div>`;
function render(){save();if(page==='home')home();if(page==='wardrobe')pixelShop();if(page==='games')games();}
function parentGlucoseFixture(){const glucose=petGlucose();return `<section class="card card-pad" id="parent-fixture-glucose"><div class="card-title">A little glucose check <span class="tiny">DEMO DATA</span></div><div class="reading"><strong>${reading}</strong><b>${glucose==='low'?'↘':glucose==='high'?'↗':'→'}</b><span>mg/dL</span></div><div class="range-label">${glucose==='range'?'Within your set range · Steady and cozy':glucose==='low'?'Low · Follow your personal care plan':'High · Follow your personal care plan'}</div><svg class="chart" viewBox="0 0 300 62" aria-label="Illustrative glucose graph"><path d="M0 10H300M0 48H300" stroke="#e8eddf" stroke-dasharray="4 4"/><path d="M0 32L12 30L24 34L36 28L48 31L60 23L72 26L84 22L96 28L108 27L120 35L132 33L144 38L156 35L168 31L180 33L192 26L204 24L216 27L228 21L240 23L252 26L264 22L280 25L296 24" fill="none" stroke="#a5b98e" stroke-width="2.5"/><circle cx="296" cy="24" r="3.5" fill="#8ea77a"/></svg><div class="chart-labels"><span>3 hours ago</span><span>Now · simulated</span></div><p>Your range: ${state.thresholds.low}–${state.thresholds.high} mg/dL · Settings available under Preferences &amp; devices.</p></section>`}
function home(){glucose=petGlucose();content.innerHTML=greeting('Small steps. A softer day.','A little care for you. A little joy for Miso.','HEY THERE, WELCOME HOME ☀')+`<div class="dashboard"><section class="card"><div class="world-top"><div><strong>Miso’s little world</strong><small> &nbsp; Your everyday companion</small></div><button class="level" id="rename-character">✎ Rename · Free</button></div><div class="scene"><canvas id="room" width="960" height="620" aria-label="Illustration of Miso wearing a CGM and insulin pump in ${roomName()}"></canvas><span class="scene-caption">${roomName().toUpperCase()}</span><button class="scene-sound" id="sound">${sound?'♫ Sound on':'♪ Sound off'}</button></div><div class="world-bottom"><div class="now-doing"><span id="action-icon">✧</span><div><strong id="action-title">Miso’s little routine</strong><small id="action-detail">Making room for the little things.</small></div></div><button class="secondary" id="activity">Choose activity ↗</button></div><div id="activity-tray" class="activity-tray">${activityButtons()}</div></section><div class="side-stack"><section class="card card-pad timer-card" id="timer-panel"></section></div></div>${mealCard()}<div class="lower"><section class="card small-card shop-teaser"><div class="eyebrow">✧ &nbsp; LITTLE THINGS, BIG JOY</div><h3>A little more you.</h3><p>A cozy sweater? A new pump patch? Make it Miso’s.</p><button class="text-link" data-page="wardrobe">Explore the shop &nbsp; ↗</button><div class="mini-items">🧶 🌱</div></section></div>`;content.innerHTML=content.innerHTML.replaceAll('Miso',escapeHTML(state.characterName));const meal=content.querySelector('.meal-card');content.querySelector('.side-stack').prepend(meal);$('#rename-character').onclick=renameCharacter;drawRoom();timerPanel();bindMealCard();$('#activity').onclick=openActivities;$('#sound').onclick=toggleSound;bindWorldInteractions()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(b){setActivity(b.dataset.act);if(modal.open)modal.close()}});
function timerPanel(){const el=$('#timer-panel');if(!el)return;if(state.timer){let secs=Math.max(0,Math.ceil((state.timer.end-Date.now())/1000));el.innerHTML=`<div class="card-title">◷ &nbsp; Your meal timer <span class="tiny">DEMO EVENT</span></div><div class="timer-readout">${String(Math.floor(secs/60)).padStart(2,'0')}:${String(secs%60).padStart(2,'0')}</div><p>Started with a recent simulated carb + bolus event.</p><div class="progress"><div style="width:${Math.min(100,100*(1-secs/(state.timer.minutes*60||1)))}%"></div></div><button class="secondary" id="cancel-timer" style="width:100%">End early · no penalty</button>`;$('#cancel-timer').onclick=()=>{state.timer=null;save();timerPanel();toast('Timer ended. Taking care of yourself comes first.')};if(!secs)finishTimer();return}
const ev=eligibleMealEvent(),age=ev?Math.floor((Date.now()-ev.occurredAt)/60000):0;el.innerHTML=`<div class="card-title">◷ &nbsp; A little pause, a little reward</div><h2>${ev?'A meal event is ready.':'Waiting for a meal event.'}</h2><p>Choose a timer that works for your insulin intake.</p><div class="event-gate ${ev?'ready':''}">${ev?'✓ Demo carb + bolus event · '+(age<1?'just now':age+' min ago'):'⌑ Requires a t:slim carb + bolus event within 10 minutes.'}</div><button class="primary" id="start-meal-timer" ${ev?'':'disabled'}>${ev?'Choose my timer →':'Timer locked'}</button><div class="helper">${ev?'✦ +25 coins · One timer per event':'t:slim is not connected. Live timers are unavailable.'}</div><button class="text-link" id="test-meal-event">Test with a simulated event ↗</button>`;$('#start-meal-timer').onclick=mealEvent;$('#test-meal-event').onclick=openEventSimulator}
function mealEvent(){if(state.timer){toast('You already have a timer running.');return}const ev=eligibleMealEvent();if(!ev){toast('A carb + bolus event within the last 10 minutes is required.');timerPanel();return}showModal(`<div class="eyebrow">DEMO · RECENT CARB + BOLUS EVENT</div><h2>A little time for yourself.</h2><p>Choose a timer that works for your insulin intake.</p><div class="duration"><span id="minutes">15</span> <small style="font-size:16px">min</small></div><input aria-label="Timer minutes" id="duration" type="range" min="0" max="60" value="15"><div class="chart-labels"><span>0 min</span><span>60 min</span></div><div class="notice">Never delay food or low glucose treatment for coins. This timer does not advise when to eat. Stopping early has no penalty.</div><div class="modal-actions"><button class="secondary" id="skip">Not now</button><button class="primary" id="begin">Start timer · +25 ✦</button></div>`);$('#duration').oninput=e=>$('#minutes').textContent=e.target.value;$('#skip').onclick=()=>modal.close();$('#begin').onclick=()=>{if(!isEligibleMealEvent(ev)||state.timer){modal.close();timerPanel();toast('This event is no longer eligible. A recent, unused meal event is required.');return}let min=Number($('#duration').value);if(!Number.isInteger(min)||min<0||min>60){toast('Choose a duration from 0–60 minutes.');return}state.usedMealEvents.push(ev.id);state.timer={id:crypto.randomUUID(),eventId:ev.id,source:'demo',minutes:min,end:Date.now()+min*60000};save();modal.close();go('home');if(!min)finishTimer()}}

function finishTimer(){celebrationUntil=Date.now()+3500;const t=state.timer;if(!t)return;if(!state.claimed.includes(t.id)){state.coins+=25;state.claimed.push(t.id)}state.timer=null;save();timerPanel();toast('A little moment, well spent. +25 coins for your bank ✦')}
function shop(){let list=items.filter(i=>category==='All'||i.type===category||(category==='Accessories'&&['Eyewear','Scarves'].includes(i.type)));content.innerHTML=greeting('A whole world of little possibilities.','Neon nights, snowy mornings, or something sweet. Where will Miso unwind?','WARDROBE & SHOP')+`<div class="shop-banner"><span>✦ THE LITTLE WORLD COLLECTION</span><p>Preview every world and outfit. Collect your favorites with coins.</p></div><div class="tabs">${['All','Characters','Rooms','Clothes','Accessories','Devices'].map(c=>`<button data-cat="${c}" class="${category===c?'selected':''}">${c}</button>`).join('')}</div><div class="view-grid">${list.map(i=>`<section class="card product-card"><button class="art-preview" data-preview="${i.id}" aria-label="Preview ${i.name}"><canvas data-art="${i.id}" width="960" height="620"></canvas><span>Preview ↗</span></button><div class="shop-item"><div class="eyebrow">${['Eyewear','Scarves'].includes(i.type)?'Accessories':i.type}</div><h3>${i.name}</h3><p>${i.desc}${i.premium?' · Plus preview':''}</p><button class="${state.owned.includes(i.id)?'secondary':'primary'}" data-buy="${i.id}">${(state.equipped[itemSlot(i)]|| (i.type==='Rooms'?'cozy':null))===i.id?'Equipped ✓':state.owned.includes(i.id)?'Equip':i.premium?'✧ Plus exclusive':'✦ '+i.price+' coins'}</button></div></section>`).join('')}</div>`;
document.querySelectorAll('[data-art]').forEach(canvas=>{const i=items.find(x=>x.id===canvas.dataset.art);paintWorld(canvas,i.type==='Rooms'?i.id:(state.equipped.Rooms||'cozy'),{...state.equipped,[itemSlot(i)]:i.id},'range','Reading',true,i.type!=='Rooms')});
document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{category=b.dataset.cat;shop()});document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>equipItem(b.dataset.buy));document.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>previewItem(b.dataset.preview));}
function equipItem(id){const i=items.find(x=>x.id===id),key=itemSlot(i);if(i.premium){showModal('<h2>Plus preview</h2><p>Subscriptions and payments are not available in this prototype.</p>');return false}if(!state.owned.includes(id)){if(state.coins<i.price){toast('A few more little moments will get you there.');return false}state.coins-=i.price;state.owned.push(id)}state.equipped[key]=id;save();toast(i.name+' equipped!');if(page==='wardrobe')pixelShop();return true}
function previewItem(id){const i=items.find(x=>x.id===id);showModal(`<div class="eyebrow">A LITTLE SNEAK PEEK</div><h2>${i.name}</h2><canvas id="preview-world" width="960" height="620" class="preview-world"></canvas><p>${i.desc}</p><div class="modal-actions"><button class="primary" id="preview-equip">${state.owned.includes(id)?'Equip this favorite':'Collect · '+i.price+' coins'}</button></div>`);paintWorld($('#preview-world'),i.type==='Rooms'?id:(state.equipped.Rooms||'cozy'),{...state.equipped,[itemSlot(i)]:id},'range','Reading',true);$('#preview-equip').onclick=()=>{if(equipItem(id)){modal.close();go('home')}}}

$('#demo-open').onclick=()=>showModal('<div class="eyebrow">A LITTLE LOOK AROUND</div><h2>Welcome to demo mode.</h2><p>All glucose readings and meal events here are simulated. Explore the shop or test a 0–60 minute timer with an explicitly simulated recent carb + bolus event. Your coins, clothes, timer, and settings are saved in this browser.</p>')||null;
$('#profile').onclick=()=>showModal('<h2>Your cozy corner</h2><p>This is your browser-local demo profile. Your pet, coins, and settings are kept on this device. No account or device credentials are connected.</p>');
let audioCtx,osc,gain;function toggleSound(){sound=!sound;if(sound){audioCtx=new(window.AudioContext||window.webkitAudioContext)();gain=audioCtx.createGain();gain.gain.value=.018;gain.connect(audioCtx.destination);[130.81,164.81,196].forEach(f=>{let o=audioCtx.createOscillator();o.type='sine';o.frequency.value=f;o.connect(gain);o.start()})}else audioCtx?.close();$('#sound').textContent=sound?'♫ Sound on':'♪ Sound off'}
function drawRoom(){const canvas=$('#room');if(!canvas)return;const a=currentActivity();paintWorld(canvas,state.equipped.Rooms||'cozy',state.equipped,petGlucose(),a,false,false,Date.now(),state.sharedMeal);updateActionCaption(a);}
setInterval(()=>{if(state.timer){if(Date.now()>=state.timer.end)finishTimer();else if(page==='home')timerPanel()}},1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state.timer&&Date.now()>=state.timer.end)finishTimer()});render();

let lastMisoFrame=0;function animateMiso(timestamp){if(timestamp-lastMisoFrame>=32){if(page==='home'&&!document.hidden)drawRoom();if(page==='wardrobe'&&!document.hidden&&$('#fitting-preview')){const selected=items.find(i=>i.id===previewSelection);paintWorld($('#fitting-preview'),selected?.type==='Rooms'?selected.id:state.equipped.Rooms||'cozy',previewEquipment(selected),'range',Date.now()<tryOnUntil?'Trying on accessories':'Idle',false,false,Date.now())}lastMisoFrame=timestamp}requestAnimationFrame(animateMiso)}if(typeof requestAnimationFrame==='function')requestAnimationFrame(animateMiso);setInterval(()=>{if(page==='home'&&!state.timer)timerPanel()},1000);
